set app.tenant_slug = 'ptsc2026';

alter table public.event_settings add column if not exists hero_mobile_path text not null default '/kv-mobile.png';
alter table public.tournaments add column if not exists category_code text;
alter table public.tournaments add column if not exists workflow_status text not null default 'active';
alter table public.entries add column if not exists source_key text;
alter table public.entries add column if not exists source_status text not null default 'active';
alter table public.participants add column if not exists source_key text;
alter table public.participants add column if not exists match_key text;
alter table public.groups add column if not exists group_code text;
alter table public.group_entries add column if not exists slot_no integer;
alter table public.group_entries add column if not exists source_key text;
alter table public.group_entries add column if not exists row_fingerprint text;
alter table public.group_entries add column if not exists source_sheet text;
alter table public.group_entries add column if not exists source_page integer;
alter table public.group_entries add column if not exists source_note text not null default '';
alter table public.group_entries add column if not exists source_status text not null default 'active';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'tournaments_workflow_status_check') then
    alter table public.tournaments add constraint tournaments_workflow_status_check check (workflow_status in ('draft', 'active', 'pending_confirmation', 'archived'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'entries_source_status_check') then
    alter table public.entries add constraint entries_source_status_check check (source_status in ('draft', 'active', 'pending_confirmation', 'archived', 'missing_from_source'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'group_entries_source_status_check') then
    alter table public.group_entries add constraint group_entries_source_status_check check (source_status in ('draft', 'active', 'pending_confirmation', 'archived', 'missing_from_source'));
  end if;
end $$;

create unique index if not exists tournaments_tenant_category_code_key on public.tournaments (tenant_id, category_code) where category_code is not null and archived_at is null;
create unique index if not exists entries_tenant_source_key_key on public.entries (tenant_id, source_key) where source_key is not null and archived_at is null;
create unique index if not exists participants_tenant_source_key_key on public.participants (tenant_id, source_key) where source_key is not null and archived_at is null;
create unique index if not exists groups_tenant_group_code_key on public.groups (tenant_id, tournament_id, group_code) where group_code is not null and archived_at is null;
create unique index if not exists group_entries_tenant_slot_key on public.group_entries (tenant_id, group_id, slot_no) where slot_no is not null and archived_at is null;
create unique index if not exists group_entries_tenant_source_key_key on public.group_entries (tenant_id, source_key) where source_key is not null and archived_at is null;

create table if not exists public.source_files (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id),
  event_id uuid references public.event_settings(id),
  raw_filename text not null,
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  source_kind text not null check (source_kind in ('xlsx', 'pdf', 'markdown', 'other')),
  parser_version text,
  template_version integer,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid references auth.users(id),
  created_at timestamptz not null default now(),
  unique (tenant_id, raw_filename, sha256)
);

create table if not exists public.import_batches (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id),
  event_id uuid not null references public.event_settings(id),
  parser_version text not null,
  template_version integer not null,
  idempotency_key text not null,
  file_sha256 text not null check (file_sha256 ~ '^[0-9a-f]{64}$'),
  file_name text not null,
  status text not null check (status in ('prepared', 'rejected', 'applied', 'rolled_back')),
  payload jsonb not null default '{}'::jsonb,
  preview jsonb not null default '{}'::jsonb,
  before_snapshot jsonb,
  after_snapshot jsonb,
  created_by uuid references auth.users(id),
  created_at timestamptz not null default now(),
  applied_at timestamptz,
  rolled_back_at timestamptz,
  unique (tenant_id, event_id, parser_version, idempotency_key),
  unique (tenant_id, event_id, parser_version, file_sha256)
);

create table if not exists public.import_rows (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id),
  batch_id uuid not null references public.import_batches(id) on delete cascade,
  sheet_name text not null,
  excel_row integer not null,
  source_row_key text not null,
  category_code text not null,
  normalized_group text not null,
  slot_no integer not null,
  natural_key text not null,
  row_fingerprint text,
  source_status text not null default 'active' check (source_status in ('draft', 'active', 'pending_confirmation', 'archived', 'missing_from_source')),
  status text not null default 'created' check (status in ('created', 'updated', 'unchanged', 'error', 'missing_from_source', 'rolled_back')),
  errors jsonb not null default '[]'::jsonb,
  warnings jsonb not null default '[]'::jsonb,
  before_data jsonb,
  after_data jsonb,
  created_at timestamptz not null default now(),
  unique (batch_id, source_row_key),
  unique (batch_id, natural_key)
);

create table if not exists public.audit_logs (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenants(id),
  event_id uuid references public.event_settings(id),
  batch_id uuid references public.import_batches(id),
  actor_id uuid references auth.users(id),
  action text not null,
  table_name text,
  row_id uuid,
  before_data jsonb,
  after_data jsonb,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists source_files_tenant_idx on public.source_files (tenant_id, created_at desc);
create index if not exists import_batches_tenant_idx on public.import_batches (tenant_id, created_at desc);
create index if not exists import_rows_batch_idx on public.import_rows (tenant_id, batch_id, sheet_name, excel_row);
create index if not exists audit_logs_tenant_idx on public.audit_logs (tenant_id, created_at desc);

create trigger source_files_same_tenant before insert or update on public.source_files
for each row execute function private.enforce_same_tenant('event_settings', 'event_id');
create trigger import_batches_same_tenant before insert or update on public.import_batches
for each row execute function private.enforce_same_tenant('event_settings', 'event_id');
create trigger import_rows_same_tenant before insert or update on public.import_rows
for each row execute function private.enforce_same_tenant('import_batches', 'batch_id');
create trigger audit_logs_same_tenant before insert or update on public.audit_logs
for each row execute function private.enforce_same_tenant('event_settings', 'event_id', 'import_batches', 'batch_id');

alter table public.source_files enable row level security;
alter table public.import_batches enable row level security;
alter table public.import_rows enable row level security;
alter table public.audit_logs enable row level security;

create policy "ptsc source files admin read" on public.source_files for select to authenticated using (private.is_admin(tenant_id));
create policy "ptsc source files admin insert" on public.source_files for insert to authenticated with check (private.is_admin(tenant_id));
create policy "ptsc import batches admin read" on public.import_batches for select to authenticated using (private.is_admin(tenant_id));
create policy "ptsc import batches admin insert" on public.import_batches for insert to authenticated with check (private.is_admin(tenant_id));
create policy "ptsc import batches admin update" on public.import_batches for update to authenticated using (private.is_admin(tenant_id)) with check (private.is_admin(tenant_id));
create policy "ptsc import rows admin read" on public.import_rows for select to authenticated using (private.is_admin(tenant_id));
create policy "ptsc import rows admin insert" on public.import_rows for insert to authenticated with check (private.is_admin(tenant_id));
create policy "ptsc import rows admin update" on public.import_rows for update to authenticated using (private.is_admin(tenant_id)) with check (private.is_admin(tenant_id));
create policy "ptsc audit logs admin read" on public.audit_logs for select to authenticated using (private.is_admin(tenant_id));
create policy "ptsc audit logs admin insert" on public.audit_logs for insert to authenticated with check (private.is_admin(tenant_id));

grant select, insert on public.source_files to authenticated;
grant select, insert, update on public.import_batches to authenticated;
grant select, insert, update on public.import_rows to authenticated;
grant select, insert on public.audit_logs to authenticated;
revoke all on public.source_files, public.import_batches, public.import_rows, public.audit_logs from anon;

create or replace function private.ensure_ptsc_category(p_tenant_id uuid, p_category jsonb)
returns uuid
language plpgsql
security invoker
set search_path = public, extensions
as $$
declare
  v_sport_id uuid;
  v_tournament_id uuid;
  v_code text := upper(trim(p_category->>'code'));
  v_slug text := lower(trim(p_category->>'code'));
  v_mode text;
  v_gender text;
begin
  select id into v_sport_id
  from public.sports
  where tenant_id = p_tenant_id
    and slug = p_category->>'sport_slug'
    and archived_at is null;
  if v_sport_id is null then raise exception 'PTSC: không tìm thấy môn %', p_category->>'sport_slug'; end if;

  v_mode := case
    when p_category->>'sport_slug' in ('boi-loi', 'dien-kinh') then 'race'
    when p_category->>'code' = 'KC-DONGDOI' then 'knockout'
    when lower(coalesce(p_category->>'format_branch', '')) like '%vòng tròn%'
      and lower(coalesce(p_category->>'format_branch', '')) not like '%bk%' then 'round_robin'
    else 'group_knockout'
  end;
  v_gender := case
    when v_code like '%NAMNU%' then 'mixed'
    when v_code like '%NU%' then 'female'
    else 'male'
  end;

  insert into public.tournaments (
    tenant_id, sport_id, slug, category_code, name_vi, name_en, category_vi, category_en, gender,
    format_vi, format_en, rules_vi, rules_en, competition_mode, workflow_status, source_metadata, scoring_rule, sort_order, archived_at
  )
  values (
    p_tenant_id, v_sport_id, v_slug, v_code,
    coalesce(nullif(p_category->>'name_vi', ''), v_code), coalesce(nullif(p_category->>'name_vi', ''), v_code),
    coalesce(p_category->>'name_vi', ''), coalesce(p_category->>'name_vi', ''), v_gender,
    coalesce(p_category->>'format_branch', ''), coalesce(p_category->>'format_branch', ''),
    coalesce(p_category->>'source_note', ''), coalesce(p_category->>'source_note', ''),
    v_mode, coalesce(nullif(p_category->>'status', ''), 'active'),
    jsonb_build_object(
      'source', 'PTSC-2026-Template-Quan-Ly-11-Mon.xlsx',
      'sport_code', p_category->>'sport_code',
      'distance', p_category->>'distance',
      'group_count', nullif(p_category->>'group_count', '')::integer,
      'capacity', p_category->>'capacity',
      'format_branch', p_category->>'format_branch',
      'source_note', p_category->>'source_note'
    ),
    '{}'::jsonb, coalesce(nullif(p_category->>'source_row', '')::integer, 0), null
  )
  on conflict (tenant_id, sport_id, slug) do update set
    category_code = excluded.category_code,
    name_vi = excluded.name_vi,
    name_en = excluded.name_en,
    category_vi = excluded.category_vi,
    category_en = excluded.category_en,
    gender = excluded.gender,
    format_vi = excluded.format_vi,
    format_en = excluded.format_en,
    rules_vi = excluded.rules_vi,
    rules_en = excluded.rules_en,
    competition_mode = excluded.competition_mode,
    workflow_status = excluded.workflow_status,
    source_metadata = excluded.source_metadata,
    sort_order = excluded.sort_order,
    archived_at = null
  returning id into v_tournament_id;

  if v_tournament_id is null then
    select id into v_tournament_id from public.tournaments where tenant_id = p_tenant_id and sport_id = v_sport_id and slug = v_slug;
  end if;
  return v_tournament_id;
end;
$$;

create or replace function private.upsert_ptsc_position(p_tenant_id uuid, p_row jsonb, p_batch_id uuid default null)
returns jsonb
language plpgsql
security invoker
set search_path = public, extensions
as $$
declare
  v_code text := upper(trim(coalesce(p_row->>'category_code', '')));
  v_sport_slug text := trim(coalesce(p_row->>'sport_slug', ''));
  v_sport_id uuid;
  v_tournament_id uuid;
  v_group_id uuid;
  v_org_id uuid;
  v_entry_id uuid;
  v_participant_id uuid;
  v_source_key text := coalesce(nullif(p_row->>'natural_key', ''), v_code || '|' || upper(coalesce(nullif(p_row->>'normalized_group', ''), 'X')) || '|' || (p_row->>'slot_no'));
  v_group_code text := upper(coalesce(nullif(p_row->>'normalized_group', ''), 'X'));
  v_slot_no integer := nullif(p_row->>'slot_no', '')::integer;
  v_kind text := coalesce(nullif(p_row->>'kind', ''), 'individual');
  v_status text := coalesce(nullif(p_row->>'status', ''), 'active');
  v_unit text := nullif(trim(p_row->>'unit'), '');
  v_entry_name text;
  v_member_name text;
  v_member_index integer;
  v_member text;
  v_role text;
  v_fixture_id uuid;
begin
  if v_code = 'TEN-DOI-NAM46-CHECK' then v_code := 'TEN-DOI-NAM46'; end if;
  select id into v_sport_id from public.sports where tenant_id = p_tenant_id and slug = v_sport_slug and archived_at is null;
  select id into v_tournament_id from public.tournaments where tenant_id = p_tenant_id and category_code = v_code and archived_at is null;
  if v_sport_id is null or v_tournament_id is null then raise exception 'PTSC: hạng mục % hoặc môn % không tồn tại', v_code, v_sport_slug; end if;

  if v_unit is not null then
    insert into public.organizations (tenant_id, code, name_vi, name_en, sort_order, archived_at)
    values (p_tenant_id, 'PTSC-' || upper(substr(md5(lower(v_unit)), 1, 12)), v_unit, v_unit, 0, null)
    on conflict (tenant_id, code) do update set archived_at = null;
    select id into v_org_id from public.organizations where tenant_id = p_tenant_id and code = 'PTSC-' || upper(substr(md5(lower(v_unit)), 1, 12));
  end if;

  select string_agg(value, ' / ' order by ordinality)
    into v_entry_name
  from jsonb_array_elements_text(coalesce(p_row->'members', '[]'::jsonb)) with ordinality;
  v_member_name := coalesce(nullif(v_entry_name, ''), format('Chờ nhập · %s · %s-%s', v_code, v_group_code, v_slot_no));

  select id into v_group_id
  from public.groups
  where tenant_id = p_tenant_id and tournament_id = v_tournament_id and group_code = v_group_code and archived_at is null;
  if v_group_id is null then
    insert into public.groups (tenant_id, tournament_id, group_code, name_vi, name_en, sort_order, archived_at)
    values (p_tenant_id, v_tournament_id, v_group_code, v_group_code, v_group_code, 0, null)
    returning id into v_group_id;
  else
    update public.groups set archived_at = null where id = v_group_id and tenant_id = p_tenant_id;
  end if;

  select id into v_entry_id from public.entries where tenant_id = p_tenant_id and source_key = v_source_key and archived_at is null;
  if v_entry_id is null then
    insert into public.entries (tenant_id, tournament_id, organization_id, source_key, source_status, kind, name_vi, name_en, archived_at)
    values (p_tenant_id, v_tournament_id, v_org_id, v_source_key, v_status, v_kind, v_member_name, v_member_name, null)
    returning id into v_entry_id;
  else
    update public.entries set tournament_id = v_tournament_id, organization_id = v_org_id, source_status = v_status,
      kind = v_kind, name_vi = v_member_name, name_en = v_member_name, archived_at = null
    where id = v_entry_id and tenant_id = p_tenant_id;
  end if;

  update public.entry_members
  set archived_at = clock_timestamp()
  where tenant_id = p_tenant_id and entry_id = v_entry_id and archived_at is null;

  v_member_index := 0;
  for v_member_index, v_member, v_role in
    select ordinality::integer, value, 'Vận động viên' from jsonb_array_elements_text(coalesce(p_row->'members', '[]'::jsonb)) with ordinality
    union all
    select (100 + ordinality)::integer, value, 'Dự bị' from jsonb_array_elements_text(coalesce(p_row->'reserves', '[]'::jsonb)) with ordinality
  loop
    v_member := trim(v_member);
    if v_member = '' then continue; end if;
    select id into v_participant_id
    from public.participants
    where tenant_id = p_tenant_id
      and source_key = v_source_key || '|member|' || v_member_index
      and archived_at is null;
    if v_participant_id is null then
      select id into v_participant_id
      from public.participants
      where tenant_id = p_tenant_id
        and organization_id is not distinct from v_org_id
        and archived_at is null
        and private.entry_identity(full_name, 'individual') = private.entry_identity(v_member, 'individual')
      order by id
      limit 1;
    end if;
    if v_participant_id is null then
      insert into public.participants (tenant_id, organization_id, source_key, match_key, full_name, full_name_en, archived_at)
      values (p_tenant_id, v_org_id, v_source_key || '|member|' || v_member_index, lower(v_member), v_member, v_member, null)
      returning id into v_participant_id;
    else
      update public.participants set organization_id = v_org_id, match_key = lower(v_member), full_name = v_member, full_name_en = v_member, archived_at = null
      where id = v_participant_id and tenant_id = p_tenant_id;
    end if;
    insert into public.entry_members (tenant_id, entry_id, participant_id, role_vi, role_en, sort_order, archived_at)
    values (p_tenant_id, v_entry_id, v_participant_id, v_role, case when v_role = 'Dự bị' then 'Reserve' else 'Athlete' end, v_member_index, null)
    on conflict (entry_id, participant_id) do update set role_vi = excluded.role_vi, role_en = excluded.role_en, sort_order = excluded.sort_order, archived_at = null;
  end loop;

  insert into public.group_entries (tenant_id, group_id, entry_id, slot_no, source_key, row_fingerprint, source_sheet, source_page, source_note, source_status, archived_at)
  values (p_tenant_id, v_group_id, v_entry_id, v_slot_no, v_source_key, p_row->>'fingerprint', p_row->>'sheet', nullif(p_row->>'pdf_page', '')::integer, coalesce(p_row->>'note', ''), v_status, null)
  on conflict (tenant_id, group_id, slot_no) where slot_no is not null and archived_at is null do update set
    entry_id = excluded.entry_id, source_key = excluded.source_key, row_fingerprint = excluded.row_fingerprint,
    source_sheet = excluded.source_sheet, source_page = excluded.source_page, source_note = excluded.source_note,
    source_status = excluded.source_status, archived_at = null;

  if v_sport_slug in ('boi-loi', 'dien-kinh') then
    select id into v_fixture_id
    from public.fixtures
    where tenant_id = p_tenant_id and tournament_id = v_tournament_id
      and source_code = v_code || '-RANKING' and archived_at is null
    limit 1;
    if v_fixture_id is null then
      insert into public.fixtures (tenant_id, tournament_id, status, round_vi, round_en, source_code)
      values (p_tenant_id, v_tournament_id, 'scheduled', 'Xếp hạng trực tiếp', 'Direct ranking', v_code || '-RANKING')
      returning id into v_fixture_id;
    end if;
    insert into public.fixture_entries (tenant_id, fixture_id, entry_id, side, lane, seed_order, score, score_numeric, rank, result_detail, result_status, archived_at)
    values (p_tenant_id, v_fixture_id, v_entry_id, null, null, v_slot_no, null, null, null, '{}'::jsonb, null, null)
    on conflict (fixture_id, entry_id) do update set lane = null, seed_order = excluded.seed_order, archived_at = null;
  end if;

  insert into public.standings (tenant_id, tournament_id, group_id, entry_id)
  values (p_tenant_id, v_tournament_id, v_group_id, v_entry_id)
  on conflict (tournament_id, group_id, entry_id) do nothing;

  return jsonb_build_object('source_key', v_source_key, 'entry_id', v_entry_id, 'group_id', v_group_id);
end;
$$;

revoke all on function private.ensure_ptsc_category(uuid, jsonb) from public;
revoke all on function private.upsert_ptsc_position(uuid, jsonb, uuid) from public;
grant execute on function private.ensure_ptsc_category(uuid, jsonb) to authenticated;
grant execute on function private.upsert_ptsc_position(uuid, jsonb, uuid) to authenticated, postgres;

create or replace function public.prepare_ptsc_template_import(
  p_event_id uuid,
  p_template_version integer,
  p_parser_version text,
  p_idempotency_key text,
  p_file_sha256 text,
  p_file_name text,
  p_payload jsonb,
  p_preview jsonb
)
returns jsonb
language plpgsql
security invoker
set search_path = public, extensions
as $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_existing public.import_batches%rowtype;
  v_batch public.import_batches%rowtype;
  v_status text;
begin
  if v_tenant_id is null or not private.is_admin(v_tenant_id) then raise exception 'Không có quyền import PTSC'; end if;
  if p_event_id is null or not exists (select 1 from public.event_settings where id = p_event_id and tenant_id = v_tenant_id and archived_at is null) then raise exception 'Sự kiện PTSC không hợp lệ'; end if;
  if p_template_version is distinct from 1 or p_parser_version is distinct from 'ptsc-template-excel-v1' or length(trim(p_idempotency_key)) not between 1 and 200 then raise exception 'Thông tin import không hợp lệ'; end if;
  if p_file_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'SHA-256 file không hợp lệ'; end if;
  if jsonb_typeof(coalesce(p_payload->'categories', 'null'::jsonb)) <> 'array' then raise exception 'Payload PTSC thiếu categories'; end if;
  if jsonb_array_length(p_payload->'categories') <> 45 then raise exception 'Payload PTSC phải có đúng 45 hạng mục'; end if;
  if jsonb_typeof(coalesce(p_payload->'positions', 'null'::jsonb)) <> 'array' then raise exception 'Payload PTSC thiếu positions'; end if;
  if jsonb_array_length(p_payload->'positions') <> 490 then raise exception 'Payload PTSC phải có đúng 490 vị trí'; end if;
  if exists (
    select 1 from jsonb_array_elements(p_payload->'categories') as item(value)
    group by upper(trim(item.value->>'code')) having count(*) > 1
  ) then raise exception 'Payload PTSC bị trùng mã hạng mục'; end if;
  if exists (
    select 1 from jsonb_array_elements(p_payload->'positions') as item(value)
    where coalesce(item.value->>'category_code', '') = ''
      or not exists (
        select 1 from jsonb_array_elements(p_payload->'categories') as category(value)
        where upper(trim(category.value->>'code')) = case when upper(trim(item.value->>'category_code')) = 'TEN-DOI-NAM46-CHECK' then 'TEN-DOI-NAM46' else upper(trim(item.value->>'category_code')) end
      )
      or coalesce(item.value->>'slot_no', '') !~ '^[1-9][0-9]*$'
      or item.value->>'natural_key' is distinct from format('%s|%s|%s', case when upper(trim(item.value->>'category_code')) = 'TEN-DOI-NAM46-CHECK' then 'TEN-DOI-NAM46' else upper(trim(item.value->>'category_code')) end, upper(coalesce(nullif(trim(item.value->>'normalized_group'), ''), 'X')), (item.value->>'slot_no')::integer)
      or coalesce(item.value->>'id_matches', 'false') <> 'true'
      or coalesce(item.value->>'fingerprint', '') !~ '^[0-9a-f]{64}$'
      or coalesce(item.value->>'status', '') not in ('draft', 'active', 'pending_confirmation', 'archived')
      or jsonb_typeof(coalesce(item.value->'members', '[]'::jsonb)) <> 'array'
      or jsonb_typeof(coalesce(item.value->'reserves', '[]'::jsonb)) <> 'array'
      or (coalesce(item.value->>'kind', '') not in ('individual', 'pair', 'team'))
      or (item.value->>'kind' = 'individual' and jsonb_array_length(case when jsonb_typeof(item.value->'members') = 'array' then item.value->'members' else '[]'::jsonb end) > 1)
      or (item.value->>'kind' = 'pair' and jsonb_array_length(case when jsonb_typeof(item.value->'members') = 'array' then item.value->'members' else '[]'::jsonb end) > 2)
      or (item.value->>'kind' = 'team' and jsonb_array_length(case when jsonb_typeof(item.value->'members') = 'array' then item.value->'members' else '[]'::jsonb end) < 1 and item.value->>'sport_slug' not in ('pickleball', 'pickleball-lanh-dao'))
      or not exists (
        select 1 from jsonb_array_elements(p_payload->'categories') as category(value)
        where upper(trim(category.value->>'code')) = case when upper(trim(item.value->>'category_code')) = 'TEN-DOI-NAM46-CHECK' then 'TEN-DOI-NAM46' else upper(trim(item.value->>'category_code')) end
          and category.value->>'kind' = item.value->>'kind'
      )
  ) then raise exception 'Payload PTSC có dòng không hợp lệ'; end if;
  if exists (
    select item.value->>'natural_key'
    from jsonb_array_elements(p_payload->'positions') as item(value)
    group by item.value->>'natural_key' having count(*) > 1
  ) then raise exception 'Payload PTSC bị trùng khóa tự nhiên'; end if;

  insert into public.source_files (tenant_id, event_id, raw_filename, sha256, source_kind, parser_version, template_version, metadata, created_by)
  values (v_tenant_id, p_event_id, left(p_file_name, 255), p_file_sha256, 'xlsx', p_parser_version, p_template_version,
    jsonb_build_object('stats', p_payload->'stats'), auth.uid())
  on conflict (tenant_id, raw_filename, sha256) do nothing;

  select * into v_existing
  from public.import_batches
  where tenant_id = v_tenant_id and event_id = p_event_id and parser_version = p_parser_version
    and (idempotency_key = trim(p_idempotency_key) or file_sha256 = p_file_sha256)
  order by created_at desc
  limit 1
  for update;
  if v_existing.id is not null then
    if v_existing.idempotency_key = trim(p_idempotency_key) and v_existing.file_sha256 <> p_file_sha256 then
      raise exception 'Idempotency-Key đã dùng cho file khác';
    end if;
    return jsonb_build_object('import_id', v_existing.id, 'status', v_existing.status, 'reused', true, 'preview', v_existing.preview);
  end if;

  v_status := case when jsonb_array_length(coalesce(p_preview->'blockers', '[]'::jsonb)) > 0 then 'rejected' else 'prepared' end;
  insert into public.import_batches (tenant_id, event_id, parser_version, template_version, idempotency_key, file_sha256, file_name, status, payload, preview, created_by)
  values (v_tenant_id, p_event_id, p_parser_version, p_template_version, trim(p_idempotency_key), p_file_sha256, left(p_file_name, 255), v_status, p_payload, coalesce(p_preview, '{}'::jsonb), auth.uid())
  on conflict do nothing
  returning * into v_batch;

  if v_batch.id is null then
    select * into v_existing
    from public.import_batches
    where tenant_id = v_tenant_id and event_id = p_event_id and parser_version = p_parser_version
      and (idempotency_key = trim(p_idempotency_key) or file_sha256 = p_file_sha256)
    order by created_at desc
    limit 1
    for update;
    if v_existing.id is null then raise exception 'Không thể tạo batch import PTSC'; end if;
    if v_existing.idempotency_key = trim(p_idempotency_key) and v_existing.file_sha256 <> p_file_sha256 then raise exception 'Idempotency-Key đã dùng cho file khác'; end if;
    return jsonb_build_object('import_id', v_existing.id, 'status', v_existing.status, 'reused', true, 'preview', v_existing.preview);
  end if;

  insert into public.import_rows (tenant_id, batch_id, sheet_name, excel_row, source_row_key, category_code, normalized_group, slot_no, natural_key, row_fingerprint, source_status, status, after_data)
  select v_tenant_id, v_batch.id, item.value->>'sheet', (item.value->>'row_number')::integer,
    coalesce(item.value->>'source_row_key', format('%s!%s', item.value->>'sheet', item.value->>'row_number')),
    item.value->>'category_code', coalesce(item.value->>'normalized_group', 'X'), (item.value->>'slot_no')::integer,
    item.value->>'natural_key', item.value->>'fingerprint', coalesce(item.value->>'status', 'active'), 'created', item.value
  from jsonb_array_elements(p_payload->'positions') with ordinality as item(value, ordinal);

  return jsonb_build_object('import_id', v_batch.id, 'status', v_batch.status, 'reused', false, 'preview', v_batch.preview);
end;
$$;

create or replace function public.commit_ptsc_template_import(p_import_id uuid, p_confirm boolean default false)
returns jsonb
language plpgsql
security invoker
set search_path = public, extensions
as $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_batch public.import_batches%rowtype;
  v_category jsonb;
  v_position jsonb;
  v_event_id uuid;
  v_before_count integer;
  v_after_count integer;
begin
  if v_tenant_id is null or not private.is_admin(v_tenant_id) then raise exception 'Không có quyền commit import PTSC'; end if;
  select * into v_batch from public.import_batches where id = p_import_id and tenant_id = v_tenant_id for update;
  if v_batch.id is null then raise exception 'Batch import không tồn tại'; end if;
  if v_batch.status = 'applied' then return jsonb_build_object('import_id', v_batch.id, 'status', 'applied', 'reused', true); end if;
  if v_batch.status <> 'prepared' then raise exception 'Batch đang ở trạng thái %', v_batch.status; end if;
  if not p_confirm then raise exception 'Cần xác nhận commit sau preview'; end if;

  select count(*) into v_before_count from public.group_entries where tenant_id = v_tenant_id and archived_at is null and source_key is not null;
  for v_category in select value from jsonb_array_elements(coalesce(v_batch.payload->'categories', '[]'::jsonb)) loop
    perform private.ensure_ptsc_category(v_tenant_id, v_category);
  end loop;

  update public.import_rows row_data
  set before_data = to_jsonb(existing_row)
  from public.group_entries existing_row
  where row_data.batch_id = v_batch.id
    and existing_row.tenant_id = v_tenant_id
    and existing_row.source_key = row_data.natural_key
    and existing_row.archived_at is null;

  for v_position in select value from jsonb_array_elements(v_batch.payload->'positions') loop
    perform private.upsert_ptsc_position(v_tenant_id, v_position, v_batch.id);
  end loop;

  update public.group_entries existing_row
  set source_status = 'missing_from_source'
  where existing_row.tenant_id = v_tenant_id
    and existing_row.archived_at is null
    and existing_row.source_key is not null
    and not exists (
      select 1 from jsonb_array_elements(v_batch.payload->'positions') item
      where item->>'natural_key' = existing_row.source_key
    );

  update public.import_rows row_data
  set status = case when row_data.before_data is null then 'created' when row_data.before_data->>'row_fingerprint' is not distinct from row_data.row_fingerprint then 'unchanged' else 'updated' end,
      after_data = item.value
  from jsonb_array_elements(v_batch.payload->'positions') item(value)
  where row_data.batch_id = v_batch.id and row_data.natural_key = item.value->>'natural_key';

  select count(*) into v_after_count from public.group_entries where tenant_id = v_tenant_id and archived_at is null and source_key is not null;
  update public.import_batches
  set status = 'applied',
      before_snapshot = jsonb_build_object('source_position_count', v_before_count),
      after_snapshot = jsonb_build_object('source_position_count', v_after_count),
      applied_at = now()
  where id = v_batch.id and tenant_id = v_tenant_id;

  insert into public.audit_logs (tenant_id, event_id, batch_id, actor_id, action, metadata)
  values (v_tenant_id, v_batch.event_id, v_batch.id, auth.uid(), 'ptsc_template_import_commit',
    jsonb_build_object('source_position_count', jsonb_array_length(v_batch.payload->'positions')));

  return jsonb_build_object('import_id', v_batch.id, 'status', 'applied', 'source_position_count', jsonb_array_length(v_batch.payload->'positions'));
end;
$$;

create or replace function public.rollback_ptsc_template_import(p_import_id uuid)
returns jsonb
language plpgsql
security invoker
set search_path = public, extensions
as $$
declare
  v_tenant_id uuid := private.current_tenant_id();
  v_batch public.import_batches%rowtype;
begin
  if v_tenant_id is null or not private.is_admin(v_tenant_id) then raise exception 'Không có quyền rollback import PTSC'; end if;
  select * into v_batch from public.import_batches where id = p_import_id and tenant_id = v_tenant_id for update;
  if v_batch.id is null then raise exception 'Batch import không tồn tại'; end if;
  if v_batch.status = 'rolled_back' then return jsonb_build_object('import_id', v_batch.id, 'status', 'rolled_back', 'reused', true); end if;
  if v_batch.status <> 'applied' then raise exception 'Chỉ rollback batch đã applied'; end if;

  if exists (
    select 1
    from public.import_rows row_data
    join public.group_entries existing_row on existing_row.tenant_id = v_tenant_id and existing_row.source_key = row_data.natural_key and existing_row.archived_at is null
    where row_data.batch_id = v_batch.id
      and existing_row.row_fingerprint is distinct from row_data.row_fingerprint
  ) then
    raise exception 'Không thể rollback: dữ liệu đã có thay đổi mới hơn';
  end if;

  update public.group_entries existing_row
  set entry_id = (row_data.before_data->>'entry_id')::uuid,
      seed_order = nullif(row_data.before_data->>'seed_order', '')::integer,
      row_fingerprint = row_data.before_data->>'row_fingerprint',
      source_sheet = row_data.before_data->>'source_sheet',
      source_page = nullif(row_data.before_data->>'source_page', '')::integer,
      source_note = coalesce(row_data.before_data->>'source_note', ''),
      source_status = coalesce(row_data.before_data->>'source_status', 'active'),
      archived_at = nullif(row_data.before_data->>'archived_at', '')::timestamptz
  from public.import_rows row_data
  where row_data.batch_id = v_batch.id
    and row_data.before_data is not null
    and existing_row.tenant_id = v_tenant_id
    and existing_row.source_key = row_data.natural_key
    and existing_row.archived_at is null;

  update public.group_entries existing_row
  set archived_at = clock_timestamp(), source_status = 'missing_from_source'
  from public.import_rows row_data
  where row_data.batch_id = v_batch.id
    and row_data.before_data is null
    and existing_row.tenant_id = v_tenant_id
    and existing_row.source_key = row_data.natural_key
    and existing_row.archived_at is null;

  update public.entries entry_row
  set archived_at = clock_timestamp(), source_status = 'missing_from_source'
  where entry_row.tenant_id = v_tenant_id
    and entry_row.source_key in (select natural_key from public.import_rows where batch_id = v_batch.id)
    and entry_row.archived_at is null
    and not exists (
      select 1 from public.group_entries member
      where member.tenant_id = v_tenant_id and member.entry_id = entry_row.id and member.archived_at is null
    );

  update public.import_rows set status = 'rolled_back' where batch_id = v_batch.id;
  update public.import_batches set status = 'rolled_back', rolled_back_at = now() where id = v_batch.id and tenant_id = v_tenant_id;
  insert into public.audit_logs (tenant_id, event_id, batch_id, actor_id, action)
  values (v_tenant_id, v_batch.event_id, v_batch.id, auth.uid(), 'ptsc_template_import_rollback');
  return jsonb_build_object('import_id', v_batch.id, 'status', 'rolled_back');
end;
$$;

revoke all on function public.prepare_ptsc_template_import(uuid, integer, text, text, text, text, jsonb, jsonb) from public, anon;
revoke all on function public.commit_ptsc_template_import(uuid, boolean) from public, anon;
revoke all on function public.rollback_ptsc_template_import(uuid) from public, anon;
grant execute on function public.prepare_ptsc_template_import(uuid, integer, text, text, text, text, jsonb, jsonb) to authenticated;
grant execute on function public.commit_ptsc_template_import(uuid, boolean) to authenticated;
