begin
  update public.sports
  set archived_at = clock_timestamp()
  where tenant_id = v_tenant_id and slug in ('co-vua', 'co-tuong') and archived_at is null;

  insert into public.event_settings (
    tenant_id, singleton_key, event_name_vi, event_name_en, subtitle_vi, subtitle_en,
    about_vi, about_en, venue_vi, venue_en, hero_path, hero_mobile_path, start_at, end_at, archived_at
  )
  values (
    v_tenant_id, 'main',
    'Hội thao Tổng Công Ty Cổ Phần Dịch Vụ Kỹ Thuật Dầu Khí Việt Nam lần thứ 15',
    'PTSC 15th Sports Festival',
    'PTSC 2026', 'PTSC 2026', '', '', '', '', '/kv.png', '/kv-mobile.png', null, null, null
  )
  on conflict (tenant_id, singleton_key) do update set
    event_name_vi = excluded.event_name_vi,
    event_name_en = excluded.event_name_en,
    subtitle_vi = excluded.subtitle_vi,
    subtitle_en = excluded.subtitle_en,
    hero_path = coalesce(public.event_settings.hero_path, excluded.hero_path),
    hero_mobile_path = coalesce(public.event_settings.hero_mobile_path, excluded.hero_mobile_path),
    archived_at = null
  returning id into v_event_id;

  if v_event_id is null then
    select id into v_event_id from public.event_settings where tenant_id = v_tenant_id and singleton_key = 'main';
  end if;

  insert into public.source_files (tenant_id, event_id, raw_filename, sha256, source_kind, parser_version, template_version, metadata)
  values (
    v_tenant_id, v_event_id, 'docs/PTSC-2026-Template-Quan-Ly-11-Mon.xlsx',
    'eb30939822ec8b0576d5fb111ce86c6b5bf590cdf0d796d606243b44ce277b99',
    'xlsx', 'ptsc-template-excel-v1', 1, jsonb_build_object('sports', 11, 'categories', 45, 'positions', 490)
  )
  on conflict (tenant_id, raw_filename, sha256) do nothing;

  for v_sport in select value from jsonb_array_elements(v_sports) loop
    insert into public.sports (tenant_id, slug, name_vi, name_en, emoji, description_vi, description_en, rules_vi, rules_en, sort_order, archived_at)
    values (
      v_tenant_id, v_sport->>'slug', v_sport->>'name_vi', v_sport->>'name_en', v_sport->>'emoji',
      '', '', '', '', (v_sport->>'sort_order')::integer, null
    )
    on conflict (tenant_id, slug) do update set
      name_vi = excluded.name_vi, name_en = excluded.name_en, emoji = excluded.emoji,
      sort_order = excluded.sort_order, archived_at = null;
  end loop;

  for v_category in select value from jsonb_array_elements(v_categories) loop
    perform private.ensure_ptsc_category(v_tenant_id, v_category);
  end loop;

  for v_position in select value from jsonb_array_elements(v_positions) loop
    perform private.upsert_ptsc_position(v_tenant_id, v_position);
  end loop;
end
$seed$;
